"""Options for a cause, generated by code and simulated by the twin (ADR 0015).

The model never invents an option: each cause family maps to a fixed catalogue. Every option
that changes something the twin can simulate is simulated against "do nothing" with the same
draws, and carries its impact range, risks, reversibility and the conditions that would
invalidate it.

Recommendation rule: among simulated options whose net-profit change has P10 no worse than
-floor (the store's monthly materiality, scaled to the horizon) and P50 above zero, the best P50.
If none qualifies: the cause's manual step when it has one (investigate product quality, fix
tracking, an incrementality test), otherwise "monitor". Causes without a catalogue entry (fee
increase, mix shift: store-wide) get "monitor".
"""

from dataclasses import dataclass, field, replace
from decimal import Decimal
from enum import StrEnum
from uuid import UUID

from app.agent.contracts import ActionFamily
from app.twin import Action, ActionKind, Scenario, Simulation, TwinModel, simulate
from app.twin.model import Range


class OptionKind(StrEnum):
    REDUCE_BUDGET = "reduce_budget"
    PAUSE_CAMPAIGN = "pause_campaign"
    PAUSE_UNTIL_RESTOCK = "pause_until_restock"
    INCREASE_BUDGET = "increase_budget"
    PREPARE_REORDER = "prepare_reorder"
    PREPARE_PRICE_CHANGE = "prepare_price_change"
    REVIEW_SUPPLIER = "review_supplier"
    INCREMENTALITY_TEST = "incrementality_test"
    INVESTIGATE_PRODUCT_QUALITY = "investigate_product_quality"
    FIX_TRACKING = "fix_tracking"
    MONITOR = "monitor"


class Reversibility(StrEnum):
    REVERSIBLE = "reversible"  # pause <-> resume, budget restored to its previous value
    PREPARE_ONLY = "prepare_only"  # a suggestion the owner carries out (reorder, price)
    MANUAL = "manual"  # no automated action
    NONE = "none"  # monitor: nothing changes


# Causes the catalogue knows, beyond the detectors' fault families.
NEGATIVE_CAMPAIGN_PROFIT = "negative_campaign_profit"
UNDERFUNDED_CAMPAIGN = "underfunded_campaign"
EXECUTABLE = frozenset(
    {
        OptionKind.REDUCE_BUDGET,
        OptionKind.PAUSE_CAMPAIGN,
        OptionKind.PAUSE_UNTIL_RESTOCK,
        OptionKind.INCREASE_BUDGET,
    }
)
MANUAL_STEPS = frozenset(
    {
        OptionKind.INVESTIGATE_PRODUCT_QUALITY,
        OptionKind.FIX_TRACKING,
        OptionKind.INCREMENTALITY_TEST,
    }
)
DEFAULT_LEAD_TIME_DAYS = 14


@dataclass(frozen=True)
class Option:
    option_id: str
    kind: OptionKind
    action_family: ActionFamily
    entity: str  # "campaign:<id>", "product:<id>" or "store"
    actions: tuple[Action, ...]  # what the twin simulates; empty when nothing is simulated
    reversibility: Reversibility
    risks: tuple[str, ...]
    invalidated_if: tuple[str, ...]
    flags: tuple[str, ...] = ()
    simulation: Simulation | None = None

    @property
    def executable(self) -> bool:
        """An executor action exists for it (pause, resume, budget change)."""
        return self.kind in EXECUTABLE

    @property
    def impact(self) -> Range | None:
        """Net-profit change against doing nothing over the horizon, when simulated."""
        if self.simulation is None or self.simulation.undefined_reason:
            return None
        return self.simulation.change.get("net_profit")


@dataclass(frozen=True)
class OptionSet:
    cause: str
    entity: str
    options: tuple[Option, ...]
    recommended: str  # option id
    reason: str
    floor: Decimal  # the materiality floor over the horizon
    horizon_days: int = 14
    extra: dict[str, str] = field(default_factory=dict)

    def option(self, option_id: str) -> Option:
        return next(o for o in self.options if o.option_id == option_id)


def _budget(campaign: UUID, change: str, days: int | None = None) -> Action:
    return Action(kind=ActionKind.CHANGE_BUDGET, entity=campaign, change=Decimal(change), days=days)


def _pause(campaign: UUID, days: int | None = None) -> Action:
    return Action(kind=ActionKind.PAUSE_CAMPAIGN, entity=campaign, days=days)


CUT_RISKS = (
    "fewer sales of the promoted products while the budget is lower",
    "the ad platform's delivery may need time to settle after the change",
)
PAUSE_RISKS = (
    "the promoted products lose their ad-driven sales while paused",
    "the ad platform's delivery may need time to recover after a resume",
)
CPA_INVALIDATION = (
    "the campaign's cost per purchase returns to its earlier level",
    "real orders of the promoted products fall less than the twin expects after the change",
)


def _campaign_options(cause: str, campaign: UUID) -> list[Option]:
    entity = f"campaign:{campaign}"
    cut = ActionFamily.REDUCE_OR_REALLOCATE_BUDGET
    pause_family = ActionFamily.PAUSE_OR_REDUCE_CAMPAIGN
    if cause in ("cpa_drift", NEGATIVE_CAMPAIGN_PROFIT, "cannibalization"):
        flags: tuple[str, ...] = ("incrementality_test",) if cause == "cannibalization" else ()
        invalid: tuple[str, ...] = (
            (
                "an incrementality test shows the campaign's buyers would not have bought anyway",
                *CPA_INVALIDATION[1:],
            )
            if cause == "cannibalization"
            else CPA_INVALIDATION
        )
        out = [
            Option(
                f"{cause}:reduce_budget:-0.2:{campaign}",
                OptionKind.REDUCE_BUDGET,
                cut,
                entity,
                (_budget(campaign, "-0.2"),),
                Reversibility.REVERSIBLE,
                CUT_RISKS,
                invalid,
                flags,
            ),
            Option(
                f"{cause}:reduce_budget:-0.3:{campaign}",
                OptionKind.REDUCE_BUDGET,
                cut,
                entity,
                (_budget(campaign, "-0.3"),),
                Reversibility.REVERSIBLE,
                CUT_RISKS,
                invalid,
                flags,
            ),
            Option(
                f"{cause}:pause_campaign:{campaign}",
                OptionKind.PAUSE_CAMPAIGN,
                pause_family,
                entity,
                (_pause(campaign),),
                Reversibility.REVERSIBLE,
                PAUSE_RISKS,
                invalid,
                flags,
            ),
        ]
        if cause == "cannibalization":
            out.append(
                Option(
                    f"{cause}:incrementality_test:{campaign}",
                    OptionKind.INCREMENTALITY_TEST,
                    ActionFamily.MONITOR,
                    entity,
                    (),
                    Reversibility.MANUAL,
                    ("a test holds back part of the audience for its duration",),
                    ("the test shows the campaign's purchases are incremental",),
                )
            )
        return out
    if cause == UNDERFUNDED_CAMPAIGN:
        grow = ActionFamily.INCREASE_BUDGET_CAPPED
        risks = (
            "returns fall as spend grows: each extra purchase costs more than the last",
            "the response above the observed spend is extrapolated",
        )
        invalid = ("the campaign's cost per purchase rises after the increase",)
        return [
            Option(
                f"{cause}:increase_budget:0.1:{campaign}",
                OptionKind.INCREASE_BUDGET,
                grow,
                entity,
                (_budget(campaign, "0.1"),),
                Reversibility.REVERSIBLE,
                risks,
                invalid,
            ),
            Option(
                f"{cause}:increase_budget:0.2:{campaign}",
                OptionKind.INCREASE_BUDGET,
                grow,
                entity,
                (_budget(campaign, "0.2"),),
                Reversibility.REVERSIBLE,
                risks,
                invalid,
            ),
        ]
    if cause == "tracking_break":
        return [
            Option(
                f"{cause}:fix_tracking:{campaign}",
                OptionKind.FIX_TRACKING,
                ActionFamily.FIX_TRACKING,
                entity,
                (),
                Reversibility.MANUAL,
                (
                    "budget decisions on this campaign rest on unreliable platform numbers until "
                    "tracking is fixed",
                ),
                (
                    "real orders of the promoted products fall too: the problem is not only "
                    "measurement",
                ),
            ),
        ]
    return []


def _product_options(cause: str, product: UUID, model: TwinModel, horizon: int) -> list[Option]:
    entity = f"product:{product}"
    if cause == "stockout_on_promoted":
        lead = max(1, min(horizon, _lead_time_days(model, product)))
        campaigns = sorted(c.campaign_id for c in model.campaigns.values() if product in c.promoted)
        invalid = ("stock arrives earlier than the supplier lead time",)
        out = [
            Option(
                f"{cause}:pause_until_restock:{product}",
                OptionKind.PAUSE_UNTIL_RESTOCK,
                ActionFamily.PAUSE_OR_REDUCE_CAMPAIGN,
                entity,
                tuple(_pause(c, days=lead) for c in campaigns),
                Reversibility.REVERSIBLE,
                ("the campaigns' other promoted products lose their ad-driven sales while paused",),
                invalid,
            ),
            Option(
                f"{cause}:reduce_budget:-0.3:{product}",
                OptionKind.REDUCE_BUDGET,
                ActionFamily.REDUCE_OR_REALLOCATE_BUDGET,
                entity,
                tuple(_budget(c, "-0.3", days=lead) for c in campaigns),
                Reversibility.REVERSIBLE,
                CUT_RISKS,
                invalid,
            ),
            Option(
                f"{cause}:prepare_reorder:{product}",
                OptionKind.PREPARE_REORDER,
                ActionFamily.RESTOCK_PRODUCT,
                entity,
                (),
                Reversibility.PREPARE_ONLY,
                ("a reorder ties up cash until the stock sells",),
                ("demand for the product falls back before the stock arrives",),
            ),
        ]
        return [o for o in out if o.actions or o.kind is OptionKind.PREPARE_REORDER]
    if cause == "supplier_cost_increase":
        return [
            Option(
                f"{cause}:prepare_price_change:0.05:{product}",
                OptionKind.PREPARE_PRICE_CHANGE,
                ActionFamily.REVIEW_PRICING,
                entity,
                (Action(kind=ActionKind.CHANGE_PRICE, entity=product, change=Decimal("0.05")),),
                Reversibility.PREPARE_ONLY,
                ("customers may buy less at a higher price; the price response is uncertain",),
                ("sales fall more than expected after the change",),
            ),
            Option(
                f"{cause}:review_supplier:{product}",
                OptionKind.REVIEW_SUPPLIER,
                ActionFamily.REVIEW_SUPPLIER_COST,
                entity,
                (),
                Reversibility.MANUAL,
                ("another supplier may differ in quality or lead time",),
                ("the cost increase is temporary",),
            ),
        ]
    if cause == "refund_spike":
        return [
            Option(
                f"{cause}:investigate_product_quality:{product}",
                OptionKind.INVESTIGATE_PRODUCT_QUALITY,
                ActionFamily.INVESTIGATE_PRODUCT_QUALITY,
                entity,
                (),
                Reversibility.MANUAL,
                ("refunds keep costing margin until the cause is found",),
                ("refund reasons point to a delivery or listing issue rather than quality",),
            ),
        ]
    return []


def _lead_time_days(model: TwinModel, product: UUID) -> int:
    """How long a pause "until restock" lasts: the supplier lead time (an order placed now)."""
    p = model.products.get(product)
    return p.lead_time_days if p is not None and p.lead_time_days else DEFAULT_LEAD_TIME_DAYS


def catalogue(cause: str, entity: str, model: TwinModel, horizon: int = 14) -> list[Option]:
    """The options for a cause on an entity ("campaign:<id>", "product:<id>")."""
    kind, _, raw = entity.partition(":")
    if kind == "campaign":
        return _campaign_options(cause, UUID(raw))
    if kind == "product":
        return _product_options(cause, UUID(raw), model, horizon)
    return []


def monitor(cause: str, entity: str) -> Option:
    return Option(
        f"{cause}:monitor:{entity}",
        OptionKind.MONITOR,
        ActionFamily.MONITOR,
        entity,
        (),
        Reversibility.NONE,
        ("the cause keeps costing money if it is real",),
        ("the next data shows the change is material",),
    )


def recommend(options: list[Option], floor: Decimal) -> tuple[str, str]:
    """(option id, reason) by the rule in the module docstring."""
    acceptable = [
        o
        for o in options
        if o.impact is not None and o.impact.p10 >= -float(floor) and o.impact.p50 > 0
    ]
    if acceptable:
        best = max(acceptable, key=lambda o: o.impact.p50 if o.impact else 0.0)
        return (
            best.option_id,
            "best median gain among options whose downside stays within the floor",
        )
    manual = [o for o in options if o.kind in MANUAL_STEPS]
    if manual:
        return manual[0].option_id, "no simulated option beats doing nothing safely: manual step"
    return "", "no option beats doing nothing safely: monitor"


def build_options(
    model: TwinModel,
    cause: str,
    entity: str,
    *,
    floor_monthly: Decimal,
    horizon: int = 14,
) -> OptionSet:
    """Generate, simulate and rank the options for a cause."""
    floor = (floor_monthly * Decimal(horizon) / Decimal(30)).quantize(Decimal("0.01"))
    options = [
        replace(o, simulation=simulate(model, Scenario(actions=o.actions, horizon_days=horizon)))
        if o.actions
        else o
        for o in catalogue(cause, entity, model, horizon)
    ]
    chosen, reason = recommend(options, floor)
    if not chosen:
        fallback = monitor(cause, entity)
        options.append(fallback)
        chosen = fallback.option_id
    return OptionSet(
        cause=cause,
        entity=entity,
        options=tuple(options),
        recommended=chosen,
        reason=reason,
        floor=floor,
        horizon_days=horizon,
    )
